import type { HTMLAttributes } from 'react'
import { Fact } from '@/components/ui/Fact'
import { cn } from '@/lib/cn'

// Short facts about one thing (console2.css .v2-fact): each a small hairline box with its name, muted, and its value,
// so a row of them wraps cleanly. Pass `facts`, or write Fact as children. `mono` sets a value in Geist Mono (a domain,
// an ID). Six at most; a value that needs a sentence is not a fact.
export type FactItem = { name: string, value: string, mono?: boolean }

export interface FactsProps extends HTMLAttributes<HTMLDListElement> {
  facts?: FactItem[]
}

export function Facts({ facts, className, children, ...rest }: FactsProps) {
  return (
    <dl data-ds="facts" className={cn('flex flex-wrap gap-2', className)} {...rest}>
      {children ?? facts?.map(f => <Fact key={f.name} name={f.name} value={f.value} mono={f.mono} />)}
    </dl>
  )
}

export default Facts

import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/cn'

// One fact: a 24px hairline box, 12px, the name muted and the value in ink. Inside Facts (a <dl>).
export interface FactProps extends HTMLAttributes<HTMLDivElement> {
  name: string
  value?: string
  mono?: boolean
}

export function Fact({ name, value, mono, className, children, ...rest }: FactProps) {
  return (
    <div data-ds="fact" className={cn('flex min-w-0 items-center gap-1.5 border border-edge bg-surface px-2 py-1 type-meta', className)} {...rest}>
      <dt className="text-fg-muted">{name}</dt>
      <dd className={cn('min-w-0', mono && 'font-code')}>{children ?? value}</dd>
    </div>
  )
}

export default Fact

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
